from collections import deque

def shortestRoute(grid):
    R, C = len(grid), len(grid[0])
    start = next((r, c) for r in range(R) for c in range(C) if grid[r][c] == 'S')
    dist = {start: 0}
    q = deque([start])
    while q:
        y, x = q.popleft()
