        while (i > 0 && heap[(i - 1) >> 1] > heap[i]) {
          [heap[(i - 1) >> 1], heap[i]] = [heap[i], heap[(i - 1) >> 1]];
          i = (i - 1) >> 1;
        }
      };
      const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
          heap[0] = last;
          let i = 0;
          for (;;) {
            let m = i;
            const l = 2 * i + 1;
            const r = l + 1;
            if (l < heap.length && heap[l] < heap[m]) m = l;
            if (r < heap.length && heap[r] < heap[m]) m = r;
            if (m === i) break;
            [heap[m], heap[i]] = [heap[i], heap[m]];
            i = m;
          }
